-- 1. Справочники и независимые сущности
CREATE TABLE IF NOT EXISTS "exercises" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(255) NOT NULL,
    "description" TEXT,
    "animation" VARCHAR(255)
);

CREATE TABLE IF NOT EXISTS "rewards" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "amount" INTEGER NOT NULL CHECK (amount > 0)
);

CREATE TABLE IF NOT EXISTS "partners" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" TEXT NOT NULL,
    "logo" VARCHAR(255)
);

CREATE TABLE IF NOT EXISTS "items" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "partner_id" INTEGER NOT NULL REFERENCES "partners"("id") ON DELETE RESTRICT,
    "price" INTEGER NOT NULL CHECK (price > 0)
);

CREATE TABLE IF NOT EXISTS "tasks" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "reward_id" INTEGER NOT NULL REFERENCES "rewards"("id") ON DELETE RESTRICT
);

-- Таблица связи заданий и упражнений из банка
CREATE TABLE IF NOT EXISTS "exercise_in_task" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "task_id" UUID NOT NULL REFERENCES "tasks"("id") ON DELETE CASCADE,
    "exercise_id" INTEGER NOT NULL REFERENCES "exercises"("id") ON DELETE RESTRICT,
    "repeats" INTEGER NOT NULL CHECK (repeats > 0)
);

-- 2. Пользователи
CREATE TABLE IF NOT EXISTS "users" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "nickname" VARCHAR(50) NOT NULL,
    "balance" INTEGER NOT NULL DEFAULT 0 CHECK (balance >= 0),
    "email" VARCHAR(100),
    "phone_number" VARCHAR(25) NOT NULL UNIQUE,
    "password_hash" VARCHAR(255) NOT NULL, -- Увеличено для Bcrypt/Argon2
    "days_straight" INTEGER NOT NULL DEFAULT 0 CHECK (days_straight >= 0),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 3. Выполнение заданий пользователями
CREATE TABLE IF NOT EXISTS "user_tasks" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "task_id" UUID NOT NULL REFERENCES "tasks"("id") ON DELETE RESTRICT,
    "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
    "is_completed" BOOLEAN NOT NULL DEFAULT FALSE,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Журнал выполнения конкретных упражнений внутри пользовательского задания
CREATE TABLE IF NOT EXISTS "exercise_journal" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "user_task_id" UUID NOT NULL REFERENCES "user_tasks"("id") ON DELETE CASCADE,
    "exercise_id" INTEGER NOT NULL REFERENCES "exercises"("id") ON DELETE RESTRICT,
    "is_completed" BOOLEAN NOT NULL DEFAULT FALSE,
    "completed_at" TIMESTAMPTZ
);

-- 4. Единый журнал транзакций (Ledger)
CREATE TABLE IF NOT EXISTS "transactions" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT,
    "amount" INTEGER NOT NULL CHECK (amount <> 0),
    "transaction_type" VARCHAR(50) NOT NULL, -- 'TASK_REWARD', 'STORE_PURCHASE', 'STREAK_BONUS', 'PENALTY', 'COMPENSATION'

    -- Необязательные ссылки на источники операции
    "bought_item_id" UUID REFERENCES "items"("id") ON DELETE SET NULL,
    "completed_task_id" UUID REFERENCES "tasks"("id") ON DELETE SET NULL,

    "idempotency_key" VARCHAR(255) NOT NULL UNIQUE,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- Валидация целостности данных транзакции
    CONSTRAINT chk_transaction_sources CHECK (
        (transaction_type = 'STORE_PURCHASE' AND bought_item_id IS NOT NULL AND amount < 0) OR
        (transaction_type = 'TASK_REWARD' AND completed_task_id IS NOT NULL AND amount > 0) OR
        (transaction_type IN ('STREAK_BONUS', 'PENALTY', 'COMPENSATION'))
    )
);

-- Индексы для оптимизации частых запросов
CREATE INDEX idx_transactions_user_id ON "transactions"("user_id", "created_at" DESC);
CREATE INDEX idx_user_tasks_user ON "user_tasks"("user_id", "is_completed");

-- Таблица инвентаря купленных товаров/услуг
CREATE TABLE IF NOT EXISTS "user_items" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT,
    "item_id" UUID NOT NULL REFERENCES "items"("id") ON DELETE RESTRICT,

    -- Жесткая ссылка на транзакцию, по которой был куплен товар
    "transaction_id" UUID NOT NULL UNIQUE REFERENCES "transactions"("id") ON DELETE RESTRICT,

    -- Уникальный промокод/ваучер, выданный конкретно этому пользователю
    "promo_code" VARCHAR(255) NOT NULL,

    -- Статус товара: ACTIVE (активен), USED (погашен), EXPIRED (сгорел), REFUNDED (возврат)
    "status" VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',

    "purchased_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "used_at" TIMESTAMPTZ,
    "expires_at" TIMESTAMPTZ,

    CONSTRAINT chk_item_status CHECK (status IN ('ACTIVE', 'USED', 'EXPIRED', 'REFUNDED'))
);

-- Индекс для быстрого получения "Активных скидок" в мобильном приложении
CREATE INDEX idx_user_items_active ON "user_items"("user_id", "status") WHERE status = 'ACTIVE';
